input.command:
SP=<tmp>
mkdir -p "$SP" && cat > "$SP/pdftext.swift" <<'EOF'
import PDFKit
let url = URL(fileURLWithPath: CommandLine.arguments[1])
guard let doc = PDFDocument(url: url) else { print("fail"); exit(1) }
for i in 0..<doc.pageCount { print("=== PAGE \(i+1) ==="); print(doc.page(at: i)?.string ?? "") }
EOF
swift "$SP/pdftext.swift" ~/Desktop/psych251-ps3/partA/article.pdf > "$SP/article.txt" 2>&1; wc -l "$SP/article.txt"; grep -n "PAGE" "$SP/article.txt"

